question.solution:
class MyQueue:
    def __init__(self):
        self.stack_in = []
        self.stack_out = []

    def push(self, x):
        self.stack_in.append(x)

    def _shift(self):
        if not self.stack_out:
            while self.stack_in:
                self.stack_out.append(self.stack_in.pop())

    def pop(self):
        self._shift()
        if not self.stack_out:
            return None
        return self.stack_out.pop()

    def peek(self):
        self._shift()
        if not self.stack_out:
            return None
        return self.stack_out[-1]

    def empty(self):
        return not self.stack_in and not self.stack_out

q = MyQueue()
q.push(1)
q.push(2)
print(q.peek(), q.pop(), q.empty())
q.push(3)
print(q.pop(), q.pop(), q.empty())

checks:
_q = MyQueue()
_ref = []
_ok = True
for _i in range(200):
    if _i % 3 == 2 and _ref:
        if _q.pop() != _ref.pop(0):
            _ok = False
            break
    else:
        _q.push(_i)
        _ref.append(_i)
assert _ok, '入队/出队交错 200 次，出队顺序应与普通队列完全一致（两个栈要配合好）'
